// Verifies the TypeScript engine against outputs of the Python reference engine.
// fixtures/parity_cases.json is generated by `python -m inventoryiq.pipeline --source synthetic --update-fixtures`
// (synthetic data, committed). public/data/reference_plan.json is the live dataset's reference plan.
import { existsSync, readFileSync } from "node:fs";
import path from "node:path";
import { describe, expect, it } from "vitest";
import { recommend, type EngineLine, type Recommendation } from "@/lib/engine/engine";
import type { Settings } from "@/lib/types";

type Expected = Record<string, unknown>;
interface Case {
  name: string;
  settings: Settings;
  capacity: Record<string, number>;
  planningDay: number;
  lines: EngineLine[];
  expected: Expected[];
}

const camel = (s: string) => s.replace(/_([a-z])/g, (_, c: string) => c.toUpperCase());

function compare(rec: Recommendation, exp: Expected, label: string) {
  for (const [k, v] of Object.entries(exp)) {
    if (k === "series") continue;
    const key = camel(k) as keyof Recommendation;
    const got = rec[key] as unknown;
    const where = `${label} ${rec.id} ${k}`;
    if (v === null) {
      // Python NaN/inf is exported as null; TS uses null or NaN for undefined values
      expect(got === null || (typeof got === "number" && !Number.isFinite(got)), where).toBe(true);
    } else if (typeof v === "number") {
      expect(typeof got, where).toBe("number");
      const tol = Math.max(1e-6, Math.abs(v) * 1e-7);
      expect(Math.abs((got as number) - v), where).toBeLessThanOrEqual(tol);
    } else {
      expect(got, where).toEqual(v);
    }
  }
}

const fixturePath = path.resolve(__dirname, "../../fixtures/parity_cases.json");
const cases: Case[] = existsSync(fixturePath) ? JSON.parse(readFileSync(fixturePath, "utf8")).cases : [];

describe("Python parity (committed synthetic fixture)", () => {
  it("fixture is present", () => {
    expect(cases.length).toBeGreaterThanOrEqual(4);
  });
  for (const c of cases) {
    it(`case ${c.name}: every field matches the Python reference`, () => {
      const recs = recommend(c.lines, c.settings, c.capacity, c.planningDay);
      expect(recs.length).toBe(c.expected.length);
      const byId = new Map(recs.map((r) => [r.id, r]));
      for (const exp of c.expected) compare(byId.get(exp.series as string)!, exp, c.name);
    });
  }
});

const livePath = path.resolve(__dirname, "../../public/data/reference_plan.json");
const linesPath = path.resolve(__dirname, "../../public/data/lines.json");
describe.runIf(existsSync(livePath) && existsSync(linesPath))("Python parity (current app dataset)", () => {
  it("default plan matches reference_plan.json", () => {
    const ref = JSON.parse(readFileSync(livePath, "utf8"));
    const lines: EngineLine[] = JSON.parse(readFileSync(linesPath, "utf8"));
    const recs = recommend(lines, ref.settings, ref.capacity, ref.planningDay);
    for (const r of recs) compare(r, ref.results[r.id], "live");
  });
});
